describe('Polling stops when navigating away from page', () => {
  let pollingSpy;
  let pollingIntervalId;

  beforeEach(() => {
    cy.visit('http://localhost:3000');
    pollingSpy = cy.spy();
  });

  afterEach(() => {
    if (pollingIntervalId) {
      clearInterval(pollingIntervalId);
    }
  });

  it('should stop polling when user navigates to a different page', () => {
    cy.window().then((win) => {
      let pollCount = 0;
      pollingIntervalId = setInterval(() => {
        pollCount++;
        pollingSpy();
        cy.request('GET', '/api/data').then((response) => {
          expect(response.status).to.equal(200);
        });
      }, 1000);

      win.pollingActive = true;
    });

    cy.get('[data-testid="polling-status"]').should('contain', 'Polling active');

    cy.get('[data-testid="navigate-button"]').click();

    cy.url().should('include', '/other-page');

    cy.window().then((win) => {
      expect(win.pollingActive).to.be.false;
    });

    cy.wait(2000);

    const initialCallCount = pollingSpy.callCount;
    cy.wait(1500);
    expect(pollingSpy.callCount).to.equal(initialCallCount);
  });

  it('should handle rapid navigation without memory leaks', () => {
    cy.window().then((win) => {
      let activePolls = 0;

      win.startPolling = () => {
        activePolls++;
        const id = setInterval(() => {
          cy.request('GET', '/api/data').catch(() => {});
        }, 500);
        return id;
      };

      win.stopPolling = (id) => {
        clearInterval(id);
        activePolls--;
      };

      win.getActivePolls = () => activePolls;
    });

    cy.get('[data-testid="start-polling"]').click();
    cy.window().then((win) => {
      expect(win.getActivePolls()).to.equal(1);
    });

    cy.get('[data-testid="navigate-button"]').click();
    cy.url().should('include', '/other-page');

    cy.window().then((win) => {
      expect(win.getActivePolls()).to.equal(0);
    });

    cy.go('back');
    cy.get('[data-testid="start-polling"]').click();

    cy.window().then((win) => {
      expect(win.getActivePolls()).to.equal(1);
    });

    cy.get('[data-testid="navigate-button"]').click();
    cy.window().then((win) => {
      expect(win.getActivePolls()).to.equal(0);
    });
  });

  it('should cleanup polling on page unload event', () => {
    cy.window().then((win) => {
      let pollingCleanedUp = false;

      const pollInterval = setInterval(() => {
        cy.request('GET', '/api/data').catch(() => {});
      }, 1000);

      win.addEventListener('beforeunload', () => {
        clearInterval(pollInterval);
        pollingCleanedUp = true;
      });

      win.isPollingCleanedUp = () => pollingCleanedUp;
    });

    cy.get('[data-testid="polling-status"]').should('be.visible');

    cy.visit('http://localhost:3000/other-page');

    cy.window().then((win) => {
      expect(win.isPollingCleanedUp()).to.be.true;
    });
  });

  it('should not make API calls after navigation away', () => {
    let apiCallCount = 0;

    cy.intercept('GET', '/api/data', (req) => {
      apiCallCount++;
      req.reply({
        statusCode: 200,
        body: { data: 'test' }
      });
    }).as('pollingRequest');

    cy.get('[data-testid="start-polling"]').click();

    cy.wait('@pollingRequest');
    cy.wait('@pollingRequest');

    const callsBeforeNavigation = apiCallCount;

    cy.get('[data-testid="navigate-button"]').click();
    cy.url().should('include', '/other-page');

    cy.wait(3000);

    expect(apiCallCount).to.equal(callsBeforeNavigation);
  });
});
